Source code in <code>civitas/gateway/core.py</code> <pre><code>async def on_stop(self) -&gt; None:
    if self._grpc_server is not None:
        await self._grpc_server.stop()
        self._grpc_server = None

    if self._h3_server is not None:
        await self._h3_server.stop()
        self._h3_server = None

    if self._uvicorn_server is not None:
        self._uvicorn_server.should_exit = True
        self._uvicorn_server = None

    if self._server_task is not None:
        try:
            await asyncio.wait_for(self._server_task, timeout=5.0)
        except TimeoutError:
            self._server_task.cancel()
            try:
                await self._server_task
            except asyncio.CancelledError:
                pass
        self._server_task = None

    logger.info("HTTPGateway '%s' stopped", self.name)
</code></pre>

